32	    @Mapping(target = "identityKey", ignore = true)
33	    @Mapping(target = "possibleDuplicate", ignore = true)
34	    @Mapping(target = "possibleDuplicateOf", ignore = true)
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * Derives the owner's {@code contactPreference} from the owner's own fields:
39	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
40	     *
41	     * @param owner the owner being mapped
42	     * @return the derived contact preference
43	     */
44	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
45	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
46	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
47	    }
48	
49	    /**
50	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
51	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
52	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
53	     * case the field is absent from the response. The age in whole years is the number of complete
54	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
55	     * registration date is somehow absent the current date is used as the reference.
56	     *
57	     * @param owner the owner being mapped
58	     * @return the derived age band, or {@code null} when no birth date is present
59	     */
60	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
61	        java.time.LocalDate birthDate = owner.getBirthDate();
62	        if (birthDate == null) {
63	            return null;
64	        }
65	        java.time.LocalDate reference = owner.getRegistrationDate() != null
66	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
67	        int age = java.time.Period.between(birthDate, reference).getYears();
68	        if (age < 18) {
69	            return OwnerDto.AgeBandEnum.MINOR;
70	        }
71	        if (age < 65) {
72	            return OwnerDto.AgeBandEnum.ADULT;
73	        }
74	        return OwnerDto.AgeBandEnum.SENIOR;
75	    }
76	
77	    /**
78	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code customerCode}
79	     * (the part before the {@code '-'}), which is the owner's canonical region code baked into the
80	     * region-and-hash identity {@code '<REGION>-<HASH8>'}. When no customer code is present (e.g. seed
81	     * data) it falls back to resolving the region directly from the owner's {@code postcode} and
82	     * {@code city} through the shared {@link Region#code(String, String)}. Reading the region from the
83	     * identity keeps the locality consistent with the code an owner is issued.
84	     *
85	     * @param owner the owner being mapped
86	     * @return the derived locality
87	     */
88	    default String locality(Owner owner) {
89	        String code = owner.getCustomerCode();
90	        if (code == null) {
91	            return Region.code(owner.getPostcode(), owner.getCity());
92	        }
93	        int dash = code.indexOf('-');
94	        return dash >= 0 ? code.substring(0, dash) : code;
95	    }
96	
97	    /**
98	     * Derives the owner's numeric {@code membershipLevel} from the owner's own fields. Starts at
99	     * {@code 1}, adds {@code 1} when an email is present, adds {@code 1} when the owner's
100	     * {@code namesakeCount} is {@code 0}, and is capped at {@code 3} (level {@code 4} is reserved
101	     * for tenure).
102	     *
103	     * @param owner the owner being mapped
104	     * @return the derived membership level, between {@code 1} and {@code 3}
105	     */
106	    default Integer membershipLevel(Owner owner) {
107	        int level = 1;
108	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
109	        if (hasEmail) {
110	            level++;
111	        }
112	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
113	        if (uniqueName) {
114	            level++;
115	        }
116	        return Math.min(level, 3);
117	    }
118	
119	    /**
120	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
121	     * where {@code YY} is the last two digits of the {@code registrationDate} year (e.g.
122	     * {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null} when either the customer code or the
123	     * registration date is absent.
124	     *
125	     * @param owner the owner being mapped
126	     * @return the formatted membership number, or {@code null} when it cannot be derived
127	     */
128	    default String membershipNumber(Owner owner) {
129	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
130	            return null;
131	        }
132	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
133	    }
134	
135	    /**
136	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
137	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
138	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
139	     * the customer code is absent.
140	     *
141	     * @param owner the owner being mapped
142	     * @return the Luhn check digit, or {@code null} when no customer code is present
143	     */
144	    default Integer checkDigit(Owner owner) {
145	        String code = owner.getCustomerCode();
146	        if (code == null) {
147	            return null;
148	        }
149	        int sum = 0;
150	        boolean dbl = true;
151	        for (int i = code.length() - 1; i >= 0; i--) {
152	            char c = code.charAt(i);
153	            if (c < '0' || c > '9') {
154	                continue;
155	            }
156	            int d = c - '0';
157	            if (dbl) {
158	                d *= 2;
159	                if (d > 9) {
160	                    d -= 9;
161	                }
162	            }
163	            sum += d;
164	            dbl = !dbl;
165	        }
166	        return (10 - (sum % 10)) % 10;
167	    }
168	
169	    /**
170	     * Formats the owner's stored E.164 {@code telephone} for human display: the country calling
171	     * code, a space, then the national-significant digits grouped in threes separated by spaces
172	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw {@code telephone}
173	     * field keeps the unformatted E.164 value. The split between the country code and the national
174	     * digits mirrors the recognised calling codes of the {@code TelephoneNormalizer}: Australian
175	     * {@code +61} (9 national digits) and North American {@code +1} (10); an unrecognised or
176	     * malformed value falls back to a single leading digit. Returns the value unchanged when it is
177	     * {@code null}, blank, or not in E.164 form.
178	     *
179	     * @param owner the owner being mapped
180	     * @return the human-formatted telephone, or the raw value when it cannot be formatted
181	     */
182	    default String telephoneDisplay(Owner owner) {
183	        String telephone = owner.getTelephone();
184	        if (telephone == null || telephone.isBlank() || !telephone.startsWith("+")) {
185	            return telephone;
186	        }
187	        String digits = telephone.substring(1);
188	        int codeLength = (digits.startsWith("61") && digits.length() == 2 + 9) ? 2 : 1;
189	        String countryCode = digits.substring(0, codeLength);
190	        String national = digits.substring(codeLength);
191	        StringBuilder grouped = new StringBuilder();
192	        for (int i = 0; i < national.length(); i++) {
193	            if (i > 0 && i % 3 == 0) {
194	                grouped.append(' ');
195	            }
196	            grouped.append(national.charAt(i));
197	        }
198	        return "+" + countryCode + " " + grouped;
199	    }
200	
201	    Owner toOwner(OwnerDto ownerDto);
202	
203	    @Mapping(target = "id", ignore = true)
204	    @Mapping(target = "pets", ignore = true)
