213	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
214	        ownerPageDto.setPage(ownerPage.getNumber());
215	        ownerPageDto.setSize(ownerPage.getSize());
216	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
217	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
218	        return ownerPageDto;
